--
-- mtx_overlay.vhd - replacement for the OS tape routine INOUT (0AAE..0B05) and the tape bit routines below it (0A60..0AAD)
--
-- Generated by sim/make_overlay.py. Copies the next DE bytes of the .mtx stream to (HL).
-- HL = address, DE = byte count, (FD68) = 0 SAVE, (FD67) <> 0 VERIFY. A 18 byte read to C011
-- starts a new file (rewind). VERIFY compares; a name not on the tape gives No data. Leaves through RESint (0B06).
-- Ports: 8E read = next byte; 8F write bit 0 = rewind, read bit 0 = byte ready, bit 1 = end of file.
--

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity mtx_overlay is
  port
    (
    addr : in  std_logic_vector(15 downto 0);
    hit  : out std_logic;                       -- this address is served by the overlay
    q    : out std_logic_vector(7 downto 0)
    );
end mtx_overlay;

architecture behavior of mtx_overlay is
  constant BASE : integer := 16#0A60#;
  type rom_t is array (0 to 165) of std_logic_vector(7 downto 0);
  constant rom : rom_t :=
    (
    x"21", x"02", x"C0", x"01", x"8D", x"0F", x"ED", x"B3",
    x"DB", x"8D", x"A7", x"28", x"05", x"CD", x"06", x"0B",
    x"EF", x"0F", x"C3", x"06", x"0B", x"7B", x"FE", x"14",
    x"20", x"0F", x"7A", x"A7", x"20", x"0B", x"7C", x"FE",
    x"C0", x"20", x"06", x"3E", x"02", x"D3", x"8F", x"1B",
    x"1B", x"DB", x"8F", x"CB", x"57", x"20", x"FA", x"7E",
    x"D3", x"8E", x"23", x"1B", x"7A", x"B3", x"20", x"F1",
    x"3E", x"04", x"D3", x"8F", x"C3", x"06", x"0B", x"CD",
    x"06", x"0B", x"EF", x"0B", x"CD", x"06", x"0B", x"EF",
    x"3E", x"00", x"00", x"00", x"00", x"00", x"7A", x"B3",
    x"C8", x"CD", x"10", x"0B", x"3E", x"FE", x"D3", x"05",
    x"DB", x"06", x"CB", x"47", x"28", x"E6", x"3A", x"68",
    x"FD", x"A7", x"CA", x"75", x"0A", x"7B", x"FE", x"12",
    x"20", x"1C", x"7A", x"A7", x"20", x"18", x"7C", x"FE",
    x"C0", x"20", x"13", x"7D", x"FE", x"11", x"28", x"04",
    x"FE", x"22", x"20", x"0A", x"DB", x"8F", x"E6", x"02",
    x"28", x"04", x"3E", x"01", x"D3", x"8F", x"3A", x"67",
    x"FD", x"47", x"DB", x"8F", x"1F", x"30", x"FB", x"DB",
    x"8E", x"4F", x"78", x"A7", x"28", x"06", x"7E", x"B9",
    x"20", x"A5", x"18", x"01", x"71", x"23", x"1B", x"7A",
    x"B3", x"20", x"E7", x"C3", x"60", x"0A"
    );
  signal off : integer range 0 to 65535;
begin
  off <= to_integer(unsigned(addr)) - BASE when to_integer(unsigned(addr)) >= BASE else 65535;
  hit <= '1' when off < 166 else '0';
  q   <= rom(off) when off < 166 else x"00";
end behavior;
